                 		return result;
                 	}
                 	po_rec = Purchase_Order[ID == po_id];
                 	if(po_rec.ID == null)
                 	{
                 		result.put("message","Kicks Klean Ug Purchase Order not found.");
                 		return result;
                 	}
                 	po_number = ifnull(po_rec.PO_Number,"").trim();
                 	// Store matches the Purchase Order by the voucher name text (same as the PO sync), not the lookup ID
                 	employee_voucher = ifnull(po_rec.Display_Name_Employee_Voucher,"").trim();
                 	po_status = ifnull(po_rec.PO_Status,"").trim();
                 	if(po_number == "")
                 	{
